#' Group-Sequential Design & Sample Size
#'
#' Group-sequential trial design and sample-size / events calculation for
#' survival (time-to-event), binary, and continuous endpoints using the
#' gsDesign package. Reports efficacy (and optional futility) boundaries,
#' per-look sample size, and a boundary plot. Inspired by the 
#' Jamovi-TrialPlots
#' module by highwind.
#' 
#' @param data .
#' @param endpoint .
#' @param sided .
#' @param alpha .
#' @param power .
#' @param kMax .
#' @param sfu .
#' @param sfupar .
#' @param timing .
#' @param testType .
#' @param hazards Whether the hazard ratio is assumed constant over time.
#'   Under "proportional" the design uses gsDesign::gsSurv with the single
#'   hazard ratio below. Under "non-proportional" it uses
#'   gsDesign2::gs_design_ahr with an average hazard ratio, for the
#'   delayed-separation pattern typical of immunotherapy: no treatment effect
#'   for an initial period, then the hazard ratio below. Assuming proportional
#'   hazards when the curves separate late understates the events required.
#' @param delayMonths Non-proportional hazards only. Months from randomisation
#'   during which the treatment has no effect (hazard ratio held at the value
#'   below), before the full hazard ratio applies.
#' @param hrDelayed Non-proportional hazards only. The hazard ratio during the
#'   delay period. 1 means no treatment effect at all until the delay has
#'   elapsed.
#' @param hr .
#' @param medianControl .
#' @param accrualDuration .
#' @param followupDuration .
#' @param ratio .
#' @param dropoutRate .
#' @param p1 .
#' @param p2 .
#' @param deltaMean .
#' @param stdDev .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$boundaryTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$boundaryPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$boundaryTable$asDF}
#'
#' \code{as.data.frame(results$boundaryTable)}
#'
#' @export
gsdesign <- function(
    data,
    endpoint = "survival",
    sided = "2",
    alpha = 0.05,
    power = 0.9,
    kMax = 2,
    sfu = "OF",
    sfupar = -4,
    timing = "",
    testType = "efficacy",
    hazards = "proportional",
    delayMonths = 3,
    hrDelayed = 1,
    hr = 0.7,
    medianControl = 12,
    accrualDuration = 12,
    followupDuration = 18,
    ratio = 1,
    dropoutRate = 0.05,
    p1 = 0.4,
    p2 = 0.25,
    deltaMean = 0.5,
    stdDev = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("gsdesign requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- gsdesignOptions$new(
        endpoint = endpoint,
        sided = sided,
        alpha = alpha,
        power = power,
        kMax = kMax,
        sfu = sfu,
        sfupar = sfupar,
        timing = timing,
        testType = testType,
        hazards = hazards,
        delayMonths = delayMonths,
        hrDelayed = hrDelayed,
        hr = hr,
        medianControl = medianControl,
        accrualDuration = accrualDuration,
        followupDuration = followupDuration,
        ratio = ratio,
        dropoutRate = dropoutRate,
        p1 = p1,
        p2 = p2,
        deltaMean = deltaMean,
        stdDev = stdDev)

    analysis <- gsdesignClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

